/** Public entry point for the data-grid-find-replace add-on — the only module consumers should import from. */

export {
  useDataGridFindReplace,
  type UseDataGridFindReplaceOptions,
  type UseDataGridFindReplaceResult,
} from "./use-data-grid-find-replace";
export { planReplace, type ReplaceOptions, type ReplacePlan, type ReplaceSkipReason, type ReplaceState } from "./plan-replace";

// Relative on purpose: the shadcn CLI rewrites import paths, never augmentation module names.
declare module "../data-grid/types" {
  interface GridActions {
    openFindReplace: true;
    openFind: true;
  }
}

"use client";

import { useEffect, useMemo, useState, type ComponentType } from "react";
import type { DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import { FindReplacePanel, type PanelStore } from "./find-replace-panel";
import type { PanelOptions } from "./find-replace-panel";
import type { ReplaceOptions } from "./plan-replace";

export type UseDataGridFindReplaceOptions = Pick<ReplaceOptions, "scope" | "replaceAllLimit"> & {
  /**
   * Runs after the plan is built and before it is written. Return the plan to write (it may add, drop, or
   * change patches), or `false` to cancel. The returned plan may hold at most `replaceAllLimit` patches;
   * more cancels the replace. A string patch value for a cell that holds a non-string (a number cell, say) runs through the column's `fromText`; an unparseable one is skipped. Every other value is written as given. Each patch still goes through the column's `validate`.
   * A patched row that changes or goes away, a `readOnly` grid, or an open cell editor also cancels. `signal` aborts when the find text, the replacement, or an option changes, a newer replace starts, or the panel closes; a late answer is dropped.
   */
  processReplace?: PanelOptions["processReplace"];
  /** Merged into the class list of the panel root. */
  className?: string;
  /**
   * `"loaded"` (default) steps through the matches of the loaded rows. `"result"` states that the server narrows the result by `spec.searchText`:
   * the count line shows the size of the result, and Next and Previous go on into rows that are not loaded (scroll scrolls there, pages asks for the next page).
   * Replace and Replace all stay on loaded rows. A grid that holds every row behaves the same in both.
   */
  findScope?: "loaded" | "result";
};

export type UseDataGridFindReplaceResult = {
  /** One entry of the grid's `plugins` prop: the panel, the `openFindReplace` and `openFind` commands, and their `shift+alt+Enter` and `mod+f` bindings. */
  plugin: DataGridPlugin<unknown>;
  /** Opens the panel; `"find"` (default, as Mod+F) hides the Replace field until the user expands it, `"replace"` shows it. */
  open: (mode?: "find" | "replace") => void;
  close: () => void;
};

function createPanelStore(): PanelStore {
  const listeners = new Set<() => void>();
  let state = { open: false, mode: "replace" as "find" | "replace", openCount: 0 };
  let options: PanelOptions = {};
  return {
    getOptions: () => options,
    setOptions(next) {
      const classNameChanged = options.className !== next.className || options.findScope !== next.findScope;
      options = next;
      if (!classNameChanged) return;
      state = { ...state };
      listeners.forEach((listener) => listener());
    },
    getState: () => state,
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    open(mode) {
      state = { open: true, mode, openCount: state.openCount + 1 };
      listeners.forEach((listener) => listener());
    },
    setMode(mode) {
      if (!state.open || state.mode === mode) return;
      state = { ...state, mode };
      listeners.forEach((listener) => listener());
    },
    close() {
      if (!state.open) return;
      state = { ...state, open: false };
      listeners.forEach((listener) => listener());
    },
  };
}

/**
 * Find and replace for a grid: a panel with Find and Replace fields that shares the quick search
 * (highlights, next/previous) and writes through each column's text codec as one undoable change.
 * Pass `plugin` in the grid's `plugins`; `shift+alt+Enter` opens it with Replace and `mod+f` opens it with Find only.
 */
export function useDataGridFindReplace(options: UseDataGridFindReplaceOptions = {}): UseDataGridFindReplaceResult {
  const [panelStore] = useState(createPanelStore);
  useEffect(() => {
    panelStore.setOptions(options);
  });

  const plugin = useMemo<DataGridPlugin<unknown>>(() => {
    const Mount: ComponentType = function FindReplaceMount() {
      return <FindReplacePanel panelStore={panelStore} />;
    };
    return {
      name: "find-replace",
      Mount,
      commands: {
        openFindReplace: {
          run: (ctx) => panelStore.open(ctx.readOnly ? "find" : "replace"),
        },
        openFind: {
          run: () => panelStore.open("find"),
        },
      },
      keymap: { openFindReplace: ["shift+alt+Enter"], openFind: ["mod+f"] },
    };
  }, [panelStore]);

  return useMemo(
    () => ({ plugin, open: (mode = "find") => panelStore.open(mode), close: () => panelStore.close() }),
    [plugin, panelStore],
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useId,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type ChangeEvent,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { CaseSensitive, ChevronDown, ChevronRight, ChevronUp, Replace, ReplaceAll, WholeWord, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput } from "@/components/ui/input-group";
import { cn } from "@/lib/utils";
import { useDebouncedInput } from "@/registry/default/components/gridcn/use-debounce";
import {
  useDataGridApi,
  useDataGridLabels,
  useDataGridReadOnly,
  useDataGridScrollToCellAt,
  useDataGridSearchText,
} from "@/registry/default/components/data-grid/data-grid";
import {
  GRID_ATTR,
  type GateAbortReason,
  type GateRun,
  isComposingKey,
  isDev,
  useDataGridInputDebounce,
  useDataGridInstanceId,
  useDataGridGateTracker,
  useDataGridSelector,
  useDataGridSearchCapped,
  useDataGridSearchMatches,
  effectivePage,
  dataIndexOf,
  fullViewOf,
  pageOfFullRow,
  pageStartOf,
  pageUnitsOf,
} from "@/registry/default/components/data-grid/data-grid-sdk";
import { useFindResultWalk } from "./use-find-result-walk";
import { MAX_REPLACE_INPUT_LENGTH, parseReturnedPatches, planReplace, resolveReplaceLimit, type ReplaceOptions, type ReplacePlan } from "./plan-replace";

export type PanelStore = {
  getOptions(): PanelOptions;
  setOptions(options: PanelOptions): void;
  getState(): { open: boolean; mode: "find" | "replace"; openCount: number };
  subscribe(listener: () => void): () => void;
  open(mode: "find" | "replace"): void;
  setMode(mode: "find" | "replace"): void;
  close(): void;
};

/** Replace options plus the panel's own. */
export type PanelOptions = ReplaceOptions & {
  processReplace?: (ctx: { plan: ReplacePlan; signal: AbortSignal }) => ReplacePlan | false | Promise<ReplacePlan | false>;
  className?: string;
  findScope?: "loaded" | "result";
};

type PanelProps = { panelStore: PanelStore };

type Status = { kind: "replaced"; replaced: number; skipped: number; more: boolean } | { kind: "validating" } | { kind: "cancelled" } | null;


/** True when a row the plan writes is gone or is another object since the plan was built. */
function patchedRowsChanged(before: { data: readonly unknown[]; getRowId: (row: never, index: number) => string }, after: { data: readonly unknown[]; getRowId: (row: never, index: number) => string }, plan: ReplacePlan): boolean {
  const ids = new Set(plan.patches.map((patch) => patch.rowId));
  const rowsBefore = new Map<string, unknown>();
  before.data.forEach((row, index) => {
    if (row === undefined) return;
    const id = before.getRowId(row as never, index);
    if (ids.has(id)) rowsBefore.set(id, row);
  });
  let seen = 0;
  for (let index = 0; index < after.data.length; index++) {
    const row = after.data[index];
    if (row === undefined) continue;
    const id = after.getRowId(row as never, index);
    if (!rowsBefore.has(id)) continue;
    seen++;
    if (rowsBefore.get(id) !== row) return true;
  }
  return seen < rowsBefore.size;
}

function isUsablePlan(plan: unknown, limit: number): plan is ReplacePlan {
  if (typeof plan !== "object" || plan === null) return false;
  const { patches } = plan as { patches?: unknown };
  if (!Array.isArray(patches) || patches.length > limit) return false;
  return patches.every((patch: unknown) => typeof patch === "object" && patch !== null && typeof (patch as { rowId?: unknown }).rowId === "string" && typeof (patch as { columnId?: unknown }).columnId === "string");
}

export function FindReplacePanel({ panelStore }: PanelProps): ReactNode {
  const { open, mode, openCount } = useSyncExternalStore(panelStore.subscribe, panelStore.getState, panelStore.getState);
  if (!open) return null;
  return createPortal(<PanelBody key={openCount} panelStore={panelStore} showReplace={mode === "replace"} />, document.body);
}

function PanelBody({ panelStore, showReplace }: PanelProps & { showReplace: boolean }): ReactNode {
  const api = useDataGridApi();
  const labels = useDataGridLabels().findReplace;
  const readOnly = useDataGridReadOnly();
  const instanceId = useDataGridInstanceId();
  const replaceRowId = useId();
  const matches = useDataGridSearchMatches();
  const capped = useDataGridSearchCapped();
  const searchedText = useDataGridSearchText();
  const scrollToCell = useDataGridScrollToCellAt();
  const resultExceedsLoaded = useDataGridSelector<unknown, boolean>((state) => state.totalRowCount !== undefined || state.sortMode === "server" || state.filterMode === "server");
  const resultScope = resultExceedsLoaded && panelStore.getOptions().findScope === "result";
  const scopeText = resultScope ? labels.scopeResult : labels.scopeLoadedRows;
  const showScope = resultExceedsLoaded && scopeText !== "";
  const totalRowCount = useDataGridSelector<unknown, number | null | undefined>((state) => state.totalRowCount);
  const sortState = useDataGridSelector<unknown, unknown>((state) => state.sortState);
  const filterState = useDataGridSelector<unknown, unknown>((state) => state.filterState);
  const scopeId = useId();

  const delayMs = useDataGridInputDebounce();
  const [replacement, setReplacement] = useState("");
  const [searchOptions, setSearchOptions] = useState(() => api.store.getState().searchOptions);
  const [storedCursor, setCursor] = useState(0);
  const cursor = Math.max(0, Math.min(storedCursor, matches.length - 1));
  // restart at the first hit during render when the query changes; a data change keeps the position
  const queryKey = `${JSON.stringify(searchedText)}${searchOptions.matchCase}${searchOptions.wholeCell}`;
  const [lastQueryKey, setLastQueryKey] = useState(queryKey);
  if (lastQueryKey !== queryKey) {
    setLastQueryKey(queryKey);
    setCursor(0);
  }
  const [status, setStatus] = useState<Status>(null);
  const [position, setPosition] = useState<{ top: number; end: number; rtl: boolean }>({ top: 8, end: 8, rtl: false });
  const findRef = useRef<HTMLInputElement | null>(null);
  const applyTokenRef = useRef(0);
  const hookRunRef = useRef<GateRun | null>(null);
  const gates = useDataGridGateTracker();
  const abortHook = (reason?: GateAbortReason) => {
    if (hookRunRef.current) gates.abortRun(hookRunRef.current, reason);
  };
  const replacedRef = useRef<Map<string, Set<string>>>(new Map());
  const [opener] = useState(() => {
    const grid = document.querySelector(`[${GRID_ATTR.instance}="${CSS.escape(instanceId)}"]`);
    return grid !== null && grid.contains(document.activeElement) ? (document.activeElement as HTMLElement) : null;
  });

  useEffect(() => {
    findRef.current?.focus();
    findRef.current?.select();
    return () => {
      applyTokenRef.current++;
      abortHook("cancelled");
    };
  }, []);

  const findInput = useDebouncedInput(searchedText, (text) => api.actions.setSearch(text, searchOptions), { delayMs });
  const find = findInput.inputValue;
  const jumpOnCommitRef = useRef<string | null>(null);

  useEffect(() => {
    replacedRef.current.clear();
    setStatus(null);
    applyTokenRef.current++;
    abortHook();
  }, [searchedText, searchOptions]);

  const closePanel = () => {
    panelStore.close();
    if (!opener) return;
    if (opener.isConnected && opener.closest("[role='columnheader']")) opener.focus();
    else api.focus();
  };

  useLayoutEffect(() => {
    const place = () => {
      const grid = document.querySelector(`[${GRID_ATTR.instance}="${CSS.escape(instanceId)}"]`);
      if (!grid) return;
      const rect = grid.getBoundingClientRect();
      const top = Math.max(8, rect.top + 8);
      const rtl = getComputedStyle(grid).direction === "rtl";
      const end = Math.max(8, (rtl ? rect.left : window.innerWidth - rect.right) + 24);
      setPosition((current) => (current.top === top && current.end === end && current.rtl === rtl ? current : { top, end, rtl }));
    };
    place();
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    // the root settles its `dir` after the first paint
    const grid = document.querySelector(`[${GRID_ATTR.instance}="${CSS.escape(instanceId)}"]`);
    const observer = new MutationObserver(place);
    if (grid) observer.observe(grid, { attributes: true, attributeFilter: ["dir"] });
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
      observer.disconnect();
    };
  }, [instanceId]);

  const runSearch = (text: string, options: { matchCase: boolean; wholeCell: boolean }) => {
    findInput.cancel();
    api.actions.setSearch(text, options);
  };

  const goTo = useCallback(
    (index: number) => {
      const list = api.store.getState().searchMatches;
      if (list.length === 0) return;
      const wrapped = ((index % list.length) + list.length) % list.length;
      setCursor(wrapped);
      const match = list[wrapped]!;
      const col = api.store.getState().visibleColumns.findIndex((c) => c.id === match.columnId);
      if (col === -1) return;
      const state = api.store.getState();
      let row = match.row;
      if (state.pageSize !== null) {
        const full = fullViewOf(state.viewIndex);
        const page = pageOfFullRow(full, match.row, state.pageSize);
        if (effectivePage(state.page, pageUnitsOf(full), state.pageSize) !== page) api.actions.setPage(page);
        if (api.store.getState().page !== page) return;
        row = match.row - pageStartOf(api.store.getState().viewIndex);
      }
      api.actions.setActiveCellAt({ col, row });
      scrollToCell({ col, row });
    },
    [api, scrollToCell],
  );

  const walkResetKey = useMemo(() => ({}), [queryKey, sortState, filterState]); // eslint-disable-line react-hooks/exhaustive-deps
  const walk = useFindResultWalk({ enabled: resultScope, resetKey: walkResetKey, goTo });
  const stepBy = (direction: 1 | -1) => {
    if (!walk.step(direction, cursor)) goTo(cursor + direction);
  };

  // A controlled parent applies the committed text later, so the first match is known only once searchedText has caught up.
  useEffect(() => {
    if (jumpOnCommitRef.current === null || jumpOnCommitRef.current !== searchedText) return;
    if (matches.length === 0) return;
    jumpOnCommitRef.current = null;
    goTo(0);
  }, [searchedText, matches, goTo]);

  const onFindChange = (event: ChangeEvent<HTMLInputElement>) => {
    setStatus(null);
    applyTokenRef.current++;
    abortHook();
    replacedRef.current.clear();
    jumpOnCommitRef.current = null;
    findInput.inputProps.onChange(event);
  };

  const toggle = (key: "matchCase" | "wholeCell") => {
    const next = { ...searchOptions, [key]: !searchOptions[key] };
    setSearchOptions(next);
    setStatus(null);
    replacedRef.current.clear();
    runSearch(find, next);
  };

  const canReplace = !readOnly && find.trim() !== "";

  const refOfIndex = (s: ReturnType<typeof api.store.getState>, index: number): { rowId: string; columnId: string } | null => {
    const match = s.searchMatches[index];
    if (!match) return null;
    const dataIndex = dataIndexOf(fullViewOf(s.viewIndex), match.row);
    const row = dataIndex === undefined ? undefined : s.data[dataIndex];
    if (dataIndex === undefined || row === undefined) return null;
    return { rowId: s.getRowId(row, dataIndex), columnId: match.columnId };
  };

  const refOfMatch = (): { ref: { rowId: string; columnId: string }; index: number } | null => {
    const s = api.store.getState();
    const active = s.activeCell;
    const activeColumnId = active ? s.visibleColumns[active.col]?.id : undefined;
    const start = pageStartOf(s.viewIndex);
    const activeIndex = active ? s.searchMatches.findIndex((m) => m.row === active.row + start && m.columnId === activeColumnId) : -1;
    const index = activeIndex === -1 ? cursor : activeIndex;
    const ref = refOfIndex(s, index);
    return ref ? { ref, index } : null;
  };

  const apply = (only: { rowId: string; columnId: string } | undefined, nextIndex = cursor) => {
    const s = api.store.getState();
    if (s.readOnly || s.editing !== null || find.trim() === "") return;
    const replaced = replacedRef.current;
    const replacedAt = only ? refOfIndex(s, nextIndex) : null;
    const skip = only ? undefined : (ref: { rowId: string; columnId: string }) => replaced.get(ref.rowId)?.has(ref.columnId) === true;
    const plan = planReplace(s, find, replacement, { ...panelStore.getOptions(), ...searchOptions, only, skip });
    const run = (finalPlan: ReplacePlan) => {
      if (!only) {
        if (!finalPlan.remaining) replaced.clear();
        else for (const { rowId, columnId } of finalPlan.patches) replaced.set(rowId, (replaced.get(rowId) ?? new Set()).add(columnId));
      }
      const verdict = finalPlan.patches.length === 0 ? null : api.actions.updateCells(finalPlan.patches, { source: "replace", reorder: "defer" });
      const token = ++applyTokenRef.current;
      const finish = (settled: { applied: number; skipped: readonly unknown[] } | null) => {
        setStatus({
          kind: "replaced",
          replaced: settled?.applied ?? 0,
          skipped: finalPlan.skipped.length + (settled?.skipped.length ?? 0),
          more: finalPlan.remaining,
        });
        runSearch(find, searchOptions);
        if (only) {
          const after = api.store.getState();
          const columnOrder = (columnId: string) => after.visibleColumns.findIndex((c) => c.id === columnId);
          const afterView = fullViewOf(after.viewIndex);
          const replacedRow = replacedAt ? afterView.findIndex((_, viewRow) => {
            const dataIndex = dataIndexOf(afterView, viewRow);
            const row = dataIndex === undefined ? undefined : after.data[dataIndex];
            return dataIndex !== undefined && row !== undefined && after.getRowId(row, dataIndex) === replacedAt.rowId;
          }) : -1;
          const next =
            replacedAt && replacedRow !== -1
              ? after.searchMatches.findIndex((m) => m.row > replacedRow || (m.row === replacedRow && columnOrder(m.columnId) > columnOrder(replacedAt.columnId)))
              : nextIndex;
          goTo(next === -1 ? 0 : next);
        }
      };
      if (verdict?.pending) {
        setStatus({ kind: "validating" });
        void verdict.settled?.then(
          (settled) => {
            if (token === applyTokenRef.current) finish(settled);
          },
          () => {
            if (token === applyTokenRef.current) finish(null);
          },
        );
        return;
      }
      finish(verdict);
    };

    const processReplace = panelStore.getOptions().processReplace;
    if (!processReplace) {
      run(plan);
      return;
    }
    abortHook();
    const hookRun = gates.begin("processReplace", (now) => now.readOnly || now.editing !== null);
    hookRunRef.current = hookRun;
    const hookToken = ++applyTokenRef.current;
    setStatus({ kind: "validating" });
    const limit = resolveReplaceLimit(panelStore.getOptions().replaceAllLimit);
    const current = () => hookToken === applyTokenRef.current && !hookRun.aborted;
    hookRun.signal.addEventListener("abort", () => {
      if (hookToken === applyTokenRef.current) setStatus({ kind: "cancelled" });
    });
    gates.hold(hookRun);
    void Promise.resolve()
      .then(() => processReplace({ plan, signal: hookRun.signal }))
      .then(
        (result) => {
          gates.settle(hookRun);
          if (!current()) return;
          const latest = api.store.getState();
          if (latest.readOnly || latest.editing !== null || result === false) {
            setStatus({ kind: "cancelled" });
            return;
          }
          if (!isUsablePlan(result, limit)) {
            if (isDev()) console.warn("[data-grid-find-replace] processReplace returned no plan or more patches than replaceAllLimit; the replace is cancelled");
            setStatus({ kind: "cancelled" });
            return;
          }
          if (latest.data !== s.data && patchedRowsChanged(s, latest, result)) {
            setStatus({ kind: "cancelled" });
            return;
          }
          const visible = new Set(latest.visibleColumns.map((column) => column.id));
          const hidden = result.patches.filter((patch) => !visible.has(patch.columnId));
          const skipped = [...(Array.isArray(result.skipped) ? result.skipped : []), ...hidden.map(({ rowId, columnId }) => ({ ref: { rowId, columnId }, reason: "hidden" as const }))];
          const shown = hidden.length > 0 ? result.patches.filter((patch) => visible.has(patch.columnId)) : result.patches;
          const parsed = parseReturnedPatches(latest, shown);
          run({ patches: parsed.patches, skipped: [...skipped, ...parsed.skipped], remaining: result.remaining === true });
        },
        (error: unknown) => {
          gates.settle(hookRun);
          if (!current()) return;
          if (isDev()) console.warn("[data-grid-find-replace] processReplace threw; the replace is cancelled", error);
          setStatus({ kind: "cancelled" });
        },
      );
  };

  const replaceOne = () => {
    const target = refOfMatch();
    if (target) apply(target.ref, target.index);
  };

  const onKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    event.stopPropagation();
    if (isComposingKey(event)) return;
    if ((event.ctrlKey || event.metaKey) && !event.altKey && !event.shiftKey && event.key.toLowerCase() === "f") {
      event.preventDefault();
      findRef.current?.focus();
      findRef.current?.select();
      return;
    }
    if (event.key === "Escape") {
      event.preventDefault();
      findInput.cancel();
      closePanel();
    }
  };

  const onFindKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key !== "Enter" || isComposingKey(event)) return;
    event.preventDefault();
    if (findInput.inputValue !== searchedText) {
      jumpOnCommitRef.current = findInput.inputValue;
      findInput.flush();
    } else stepBy(event.shiftKey ? -1 : 1);
  };

  const onReplaceKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key !== "Enter" || isComposingKey(event) || !canReplace) return;
    event.preventDefault();
    if (event.ctrlKey || event.metaKey) apply(undefined);
    else replaceOne();
  };

  const hasMatches = matches.length > 0;
  const resultHasRows = resultScope && typeof totalRowCount === "number" && totalRowCount > 0;
  const canStep = hasMatches || (resultHasRows && find.trim() !== "" && searchedText === find);
  const noResults = status === null && find.trim() !== "" && searchedText === find && !hasMatches && !resultHasRows;
  const statusText = (() => {
    if (status?.kind === "validating") return labels.validating;
    if (status?.kind === "cancelled") return labels.replaceCancelled;
    if (status?.kind === "replaced") return status.more ? labels.replacedAndMore(labels.replaced(status.replaced, status.skipped), labels.moreRemain) : labels.replaced(status.replaced, status.skipped);
    if (find.trim() === "") return labels.typeToSearch;
    if (searchedText !== find) return "";
    if (resultScope && typeof totalRowCount === "number") return totalRowCount > 0 ? labels.resultRows(totalRowCount) : labels.noMatches;
    return hasMatches ? labels.position(cursor + 1, matches.length, capped) : labels.noMatches;
  })();

  const optionToggle = (key: "matchCase" | "wholeCell", label: string, icon: ReactNode) => (
    <Button
      type="button"
      variant={searchOptions[key] ? "default" : "ghost"}
      size="icon"
      title={label}
      aria-label={label}
      aria-pressed={searchOptions[key]}
      data-state={searchOptions[key] ? "on" : "off"}
      onClick={() => toggle(key)}
      className={cn("shrink-0", searchOptions[key] ? "forced-colors:border-2 forced-colors:border-[Highlight] forced-colors:bg-[Highlight] forced-colors:text-[HighlightText]" : "text-muted-foreground")}
    >
      {icon}
    </Button>
  );

  // Not the Popover primitive: the panel docks to the grid corner without a trigger and keeps its own focus and Escape rules.
  return (
    <div
      role="dialog"
      aria-label={labels.dialogLabel}
      {...{ [GRID_ATTR.findReplacePanel]: "", [GRID_ATTR.keepFocus]: "" }}
      onKeyDown={onKeyDown}
      onCopy={(event) => event.stopPropagation()}
      onCut={(event) => event.stopPropagation()}
      onPaste={(event) => event.stopPropagation()}
      // body-portaled: physical offsets and `dir` follow the grid, not the page
