import { viewEntryAt } from "@/registry/default/components/data-grid/data-grid-sdk";

export type WalkDirection = 1 | -1;

type WalkView = { viewIndex: readonly number[]; data: readonly unknown[] };


/** The first view row after `from` (before it for -1) whose data row is not loaded, or -1. */
export function nextHoleRow(s: WalkView, from: number, direction: WalkDirection): number {
  for (let row = from + direction; row >= 0 && row < s.viewIndex.length; row += direction) {
    if (viewEntryAt(s, row).kind === "hole") return row;
  }
  return -1;
}

/** The index of the first match past `origin` in `direction`, or -1; matches are in view order. */
export function matchPast(matches: readonly { row: number }[], origin: number, direction: WalkDirection): number {
  if (direction === 1) return matches.findIndex((match) => match.row > origin);
  for (let index = matches.length - 1; index >= 0; index--) if (matches[index]!.row < origin) return index;
  return -1;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useDataGridApi, useDataGridScrollToCellAt } from "@/registry/default/components/data-grid/data-grid";
import { viewEntryAt } from "@/registry/default/components/data-grid/data-grid-sdk";
import { useStashedPager } from "@/registry/default/components/data-grid-pagination/data-grid-pagination";
import { matchPast, nextHoleRow, type WalkDirection } from "./result-walk";

const WAIT_LIMIT_MS = 15_000;

type Wait = { direction: WalkDirection; origin: number; hole: number; page: number; data: readonly unknown[] };

type Options = {
  enabled: boolean;
  /** A change of this key (find text, options, spec) drops a running wait. */
  resetKey: unknown;
  goTo: (index: number) => void;
};

/** Steps Next and Previous past the loaded rows of a server grid: scrolls to the next unloaded row, or asks for the next page, then activates the first match that arrives. */
export function useFindResultWalk({ enabled, resetKey, goTo }: Options) {
  const api = useDataGridApi();
  const scrollToCell = useDataGridScrollToCellAt();
  const pager = useStashedPager();
  const pagerRef = useRef(pager);
  const goToRef = useRef(goTo);
  useEffect(() => {
    pagerRef.current = pager;
    goToRef.current = goTo;
  });
  const waitRef = useRef<Wait | null>(null);
  const stopRef = useRef<(() => void) | null>(null);
  const [busy, setBusy] = useState(false);

  const cancel = useCallback(() => {
    stopRef.current?.();
    stopRef.current = null;
    waitRef.current = null;
    setBusy(false);
  }, []);

  const request = useCallback(
    (wait: Wait) => {
      waitRef.current = wait;
      if (wait.hole >= 0) scrollToCell({ col: 0, row: wait.hole });
      else pagerRef.current?.onPageChange(wait.page);
    },
    [scrollToCell],
  );

  const check = useCallback(() => {
    const wait = waitRef.current;
    if (!wait) return;
    const s = api.store.getState();
    const byPage = wait.hole < 0;
    if (byPage ? s.data === wait.data : viewEntryAt(s, wait.hole).kind === "hole") return;
    const found = matchPast(s.searchMatches, wait.origin, wait.direction);
    if (found >= 0) {
      cancel();
      goToRef.current(found);
      return;
    }
    if (byPage) {
      const next = wait.page + wait.direction;
      const reachable = next >= 1 && next <= (pagerRef.current?.pageCount ?? 0);
      if (!reachable) return cancel();
      request({ ...wait, page: next, data: s.data });
      return;
    }
    const hole = nextHoleRow(s, wait.hole, wait.direction);
    if (hole === -1) return cancel();
    request({ ...wait, hole });
  }, [api, cancel, request]);

  const step = useCallback(
    (direction: WalkDirection, cursor: number): boolean => {
      if (!enabled) return false;
      if (waitRef.current) return true;
      const s = api.store.getState();
      const matches = s.searchMatches;
      const atEdge = matches.length === 0 || (direction === 1 ? cursor >= matches.length - 1 : cursor <= 0);
      if (!atEdge) return false;
      const origin = matches.length > 0 ? matches[cursor]!.row : direction === 1 ? -1 : s.viewIndex.length;
      const paged = s.pageSize === null && typeof s.totalRowCount === "number" && pagerRef.current !== null;
      let wait: Wait;
      if (paged) {
        const page = pagerRef.current!.page + direction;
        if (page < 1 || page > pagerRef.current!.pageCount) return false;
        wait = { direction, origin: direction === 1 ? -1 : Number.MAX_SAFE_INTEGER, hole: -1, page, data: s.data };
      } else {
        const hole = nextHoleRow(s, origin, direction);
        if (hole === -1) return false;
        wait = { direction, origin, hole, page: 0, data: s.data };
      }
      request(wait);
      setBusy(true);
      const unsubscribe = api.store.subscribe(check);
      const timer = setTimeout(cancel, WAIT_LIMIT_MS);
      stopRef.current = () => {
        unsubscribe();
        clearTimeout(timer);
      };
      return true;
    },
    [api, enabled, request, check, cancel],
  );

  useEffect(() => cancel, [resetKey, cancel]);

  return { step, busy };
}

import { type AnyColumnDef, type CellPatch, type CellRef, type SearchOptions } from "@/registry/default/components/data-grid/data-grid";
import { createTextMatcher, dataIndexOf, fullViewOf, isColumnReadOnly, isUnparseable, safeFromText, selectionContainsCell, toSafeText, type DataGridReadState } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Longest find or replacement text; longer input is cut. */
export const MAX_REPLACE_INPUT_LENGTH = 1_000;
/** Longest text one replaced cell may reach. */
export const MAX_REPLACED_CELL_LENGTH = 100_000;
const DEFAULT_REPLACE_ALL_LIMIT = 10_000;
const MAX_REPLACE_ALL_LIMIT = 100_000;

/** The most cells one plan may target after `replaceAllLimit` is applied: default 10,000, clamped to 1..100,000. */
export function resolveReplaceLimit(replaceAllLimit: number | undefined): number {
  return Math.min(Math.max(Math.floor(replaceAllLimit ?? DEFAULT_REPLACE_ALL_LIMIT) || 1, 1), MAX_REPLACE_ALL_LIMIT);
}

/** What `planReplace` reads from the grid. */
export type ReplaceState = Pick<DataGridReadState, "data" | "viewIndex" | "visibleColumns" | "cellTypes" | "getRowId" | "selection">;

export type ReplaceOptions = SearchOptions & {
  /** `"view"` (default) covers every visible column of the rows the sort and filter leave, every page of a paged grid; `"selection"` covers the selected cells. */
  scope?: "view" | "selection";
  /** Most cells one plan targets; default 10,000, clamped to 1..100,000. */
  replaceAllLimit?: number;
  /** Leaves out the cells it returns `true` for; a continuation passes the cells an earlier plan replaced. */
  skip?: (ref: CellRef) => boolean;
};

/** Why a cell is not replaced; `"hidden"` marks a `processReplace` patch on a hidden column, which the panel never writes. */
export type ReplaceSkipReason = "readonly" | "unparseable" | "too-long" | "no-occurrence" | "hidden";

export type ReplacePlan = {
  patches: CellPatch[];
  skipped: { ref: CellRef; reason: ReplaceSkipReason }[];
  /** True when the limit stopped the scan and more cells match. */
  remaining: boolean;
};

type ColumnPlan = {
  column: AnyColumnDef;
  readValue: (row: unknown) => unknown;
  readText: (value: unknown) => string;
  fromText: (text: string) => { value: unknown; unparseable: boolean };
  isEmpty: (value: unknown) => boolean;
};

function planColumn(column: AnyColumnDef, cellTypes: ReplaceState["cellTypes"]): ColumnPlan | null {
  const cellType = cellTypes[column.type ?? "text"];
  if (!cellType || cellType.activate) return null;
  const toText = cellType.toSearchText ?? cellType.toText;
  const options = column.options;
  const { accessorFn, accessorKey } = column;
  return {
    column,
    readValue: accessorFn ? (row) => accessorFn(row) : (row) => (row as Record<string, unknown>)[accessorKey as string],
    readText: (value) => {
      if (value == null) return "";
      try {
        return toSafeText(toText(value, options));
      } catch {
        return toSafeText(value);
      }
    },
    fromText: (text) => {
      const parsed = safeFromText(cellType, text, options, undefined);
      return { value: parsed.value, unparseable: isUnparseable(parsed) };
    },
    isEmpty: (value) => cellType.isEmpty(value),
  };
}

/** Lowercases `text` for matching; `sourceAt` maps each folded index to its source index when lowercasing changed the length. */
function foldText(text: string, matchCase: boolean): { folded: string; sourceAt: number[] | null } {
  const lower = matchCase ? text : text.toLowerCase();
  if (lower.length === text.length) return { folded: lower, sourceAt: null };
  const parts: string[] = [];
  const sourceAt: number[] = [];
  for (let i = 0; i < text.length; ) {
    const char = String.fromCodePoint(text.codePointAt(i)!);
    const lowered = char.toLowerCase();
    parts.push(lowered);
    for (let k = 0; k < lowered.length; k++) sourceAt.push(i);
    i += char.length;
  }
  return { folded: parts.join(""), sourceAt };
}

/** Replaces every occurrence of `needle` in `text`; `null` when the result would pass the cell cap, `found: false` when no whole-character occurrence exists. */
function replaceOccurrences(text: string, needle: string, replacement: string, matchCase: boolean): { text: string; found: boolean } | null {
  const target = matchCase ? needle : needle.toLowerCase();
  const { folded, sourceAt } = foldText(text, matchCase);
  const startsOnChar = (at: number) => at === 0 || at === folded.length || sourceAt![at - 1] !== sourceAt![at];
  const spans: [number, number][] = [];
  let projected = text.length;
  for (let from = 0; ; ) {
    const at = folded.indexOf(target, from);
    if (at === -1) break;
    const end = at + target.length;
    if (sourceAt && !(startsOnChar(at) && startsOnChar(end))) {
      from = at + 1;
      continue;
    }
    const start = sourceAt ? sourceAt[at]! : at;
    const stop = sourceAt ? (end === folded.length ? text.length : sourceAt[end]!) : end;
    spans.push([start, stop]);
    projected += replacement.length - (stop - start);
    if (projected > MAX_REPLACED_CELL_LENGTH) return null;
    from = end;
  }
  let out = "";
  let cursor = 0;
  for (const [start, stop] of spans) {
    out += text.slice(cursor, start) + replacement;
    cursor = stop;
  }
  return { text: out + text.slice(cursor), found: spans.length > 0 };
}

/**
 * Plans a replace over the grid: the cells whose search text matches `find`, each with the value
 * its type parses from the replaced text. Pure — the caller writes the patches. Hole rows, hidden
 * columns, and filtered-out rows never appear; read-only cells and results the type cannot parse
 * are reported in `skipped`.
 */
export function planReplace(
  state: ReplaceState,
  find: string,
  replacement: string,
  options: ReplaceOptions & { only?: CellRef } = {},
): ReplacePlan {
  const plan: ReplacePlan = { patches: [], skipped: [], remaining: false };
  const needle = find.slice(0, MAX_REPLACE_INPUT_LENGTH).trim();
  const isMatch = createTextMatcher(needle, options);
  if (isMatch === null) return plan;

  const { matchCase = false, wholeCell = false, scope = "view", only, skip } = options;
  const to = replacement.slice(0, MAX_REPLACE_INPUT_LENGTH);
  const limit = resolveReplaceLimit(options.replaceAllLimit);
  const columns = state.visibleColumns.map((column) => planColumn(column, state.cellTypes));

  const visit = (colIndex: number, rowId: string, row: unknown): boolean => {
    const entry = columns[colIndex];
    if (!entry) return true;
    const text = entry.readText(entry.readValue(row));
    if (!isMatch(text)) return true;
    const ref = { rowId, columnId: entry.column.id };
    if (skip?.(ref)) return true;
    if (isColumnReadOnly(entry.column, row)) {
      plan.skipped.push({ ref, reason: "readonly" });
      return true;
    }
    const replaced = wholeCell ? { text: to, found: true } : replaceOccurrences(text, needle, to, matchCase);
    if (replaced === null) {
      plan.skipped.push({ ref, reason: "too-long" });
      return true;
    }
    if (!replaced.found) {
      plan.skipped.push({ ref, reason: "no-occurrence" });
      return true;
    }
    const next = replaced.text;
    if (next === text) return true;
    const { value, unparseable } = entry.fromText(next);
    if (unparseable || (next.trim() !== "" && entry.isEmpty(value))) {
      plan.skipped.push({ ref, reason: "unparseable" });
      return true;
    }
    if (plan.patches.length >= limit) {
      plan.remaining = true;
      return false;
    }
    plan.patches.push({ ...ref, value });
    return true;
  };

  const { data } = state;
  const onlySelected = scope === "selection";
  const viewIndex = onlySelected ? state.viewIndex : fullViewOf(state.viewIndex);
  for (let viewRow = 0; viewRow < viewIndex.length; viewRow++) {
    const dataIndex = dataIndexOf(viewIndex, viewRow);
    const row = dataIndex === undefined ? undefined : data[dataIndex];
    if (dataIndex === undefined || row === undefined) continue;
    const rowId = state.getRowId(row, dataIndex);
    if (only && only.rowId !== rowId) continue;
    for (let col = 0; col < columns.length; col++) {
      if (only && only.columnId !== state.visibleColumns[col]!.id) continue;
      if (onlySelected && !selectionContainsCell(state.selection, { row: viewRow, col })) continue;
      if (!visit(col, rowId, row)) return plan;
    }
    if (only) return plan;
  }
  return plan;
}

/**
 * Parses each string patch value the `processReplace` hook returns for a cell that does not hold a string, with the
 * column's `fromText`. An unparseable value drops the patch and lands in `skipped`.
 */
export function parseReturnedPatches(
  state: Pick<ReplaceState, "data" | "visibleColumns" | "cellTypes" | "getRowId">,
  patches: readonly CellPatch[],
): Pick<ReplacePlan, "patches" | "skipped"> {
  const wanted = new Set(patches.filter((patch) => typeof patch.value === "string").map((patch) => patch.rowId));
  const rows = new Map<string, unknown>();
  if (wanted.size > 0) {
    state.data.forEach((row, index) => {
      if (row === undefined) return;
      const id = state.getRowId(row as never, index);
      if (wanted.has(id) && !rows.has(id)) rows.set(id, row);
    });
  }
  const columns = new Map<string, ColumnPlan | null>();
  const out: CellPatch[] = [];
  const skipped: ReplacePlan["skipped"] = [];
  for (const patch of patches) {
    if (typeof patch.value !== "string" || !rows.has(patch.rowId)) {
      out.push(patch);
      continue;
    }
    if (!columns.has(patch.columnId)) {
      const column = state.visibleColumns.find((candidate) => candidate.id === patch.columnId);
      columns.set(patch.columnId, column ? planColumn(column, state.cellTypes) : null);
    }
    const entry = columns.get(patch.columnId);
    const current = entry?.readValue(rows.get(patch.rowId));
    if (!entry || current == null || typeof current === "string") {
      out.push(patch);
      continue;
    }
    const { value, unparseable } = entry.fromText(patch.value);
    if (unparseable) skipped.push({ ref: { rowId: patch.rowId, columnId: patch.columnId }, reason: "unparseable" });
    else out.push({ ...patch, value });
  }
  return { patches: out, skipped };
}
